**Test Cases**


```javascript
// Test case 1: Normal item decreases in quality and sellIn
const normalItem = new Item('Normal Item', 5, 10);
const shop = new Shop([normalItem]);
shop.updateQuality();
console.log(normalItem); // Output: { name: 'Normal Item', sellIn: 4, quality: 9 }

// Test case 2: Aged Brie increases in quality
const agedBrie = new Item('Aged Brie', 10, 20);
const shop2 = new Shop([agedBrie]);
shop2.updateQuality();
console.log(agedBrie); // Output: { name: 'Aged Brie', sellIn: 9, quality: 21 }

// Test case 3: Backstage passes increase in quality with varying sellIn values
const backstagePass = new Item('Backstage passes to a TAFKAL80ETC concert', 12, 30);
const shop3 = new Shop([backstagePass]);
shop3.updateQuality();
console.log(backstagePass); // Output: { name: 'Backstage passes to a TAFKAL80ETC concert', sellIn: 11, quality: 31 }

// Test case 4: Backstage passes quality drops to 0 after the concert
const backstagePass2 = new Item('Backstage passes to a TAFKAL80ETC concert', 0, 30);
const shop4 = new Shop([backstagePass2]);
shop4.updateQuality();
console.log(backstagePass2); // Output: { name: 'Backstage passes to a TAFKAL80ETC concert', sellIn: -1, quality: 0 }

```

